export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key) => String(texts[key] || key);
  const esc = (v) => String(v === undefined || v === null ? '' : v)
    .replace(/\\/g, '\\\\')
    .replace(/([_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');

  // Q32: если сохранение consent_marketing, очистка сессии или чтение события
  // (continueOnFailure на step_3/step_6/step_4) упали — в билет уходит текст
  // сбоя, а не построенный на неполных данных. esc() обязателен — format у
  // step_9: MarkdownV2. ADR-0056: отдельной карточки-подтверждения больше нет
  // (финал и вопрос о рассылке шлёт reg-profile), здесь только билет.
  if (inputs.saveConsentError || inputs.clearSessionError || inputs.readEventError) {
    const errText = esc(t('common.err.generic'));
    return { ticketText: errText, ticketReplyMarkup: {}, now: new Date().toISOString() };
  }

  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const ev = arr(inputs.records).map(flat)[0] || {};
  // W131 (ADR-0053): на онлайне билет-сообщение не обещает QR.
  const online = String(ev.format || '') === 'online';
  const eventId = String(inputs.eventId === undefined || inputs.eventId === null ? '' : inputs.eventId);
  // ADR-0034: онбординг без диплинка (голый /start) доходит сюда с пустым
  // eventId — регистрации нет, билета нет, финал ведёт в каталог Mini App.
  const hasEvent = eventId !== '';
  const miniappUrl = String(inputs.miniappUrl === undefined || inputs.miniappUrl === null ? '' : inputs.miniappUrl);
  const base = miniappUrl.endsWith('/') ? miniappUrl.slice(0, -1) : miniappUrl;
  const parseIso = (s) => Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
  const utcStamp = (iso) => {
    if (!iso) return '';
    const ms = parseIso(String(iso));
    return isFinite(ms) ? new Date(ms).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '') : '';
  };
  // W76: ссылка «Добавить в календарь» в билете.
  const calUrl = (() => {
    const start = utcStamp(ev.starts_at);
    if (!start) return '';
    let end = utcStamp(ev.ends_at);
    if (!end) {
      const ms = parseIso(String(ev.starts_at));
      end = isFinite(ms) ? new Date(ms + 3600000).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '') : '';
    }
    if (!start || !end) return '';
    const params = ['action=TEMPLATE', 'text=' + encodeURIComponent(String(ev.title || '')), 'dates=' + start + '/' + end];
    if (ev.address) params.push('location=' + encodeURIComponent(String(ev.address)));
    return 'https://calendar.google.com/calendar/render?' + params.join('&');
  })();
  // W103 (ADR-0041): кнопка входа в викторину в билете — только пока открыто
  // окно хотя бы одной викторины (диапазонные фильтры по DATE не работают, Q15).
  const nowMs = Date.now();
  const quizActive = arr(inputs.quizRecords).map(flat).some((q) => {
    const st = parseIso(String(q.starts_at || ''));
    const en = parseIso(String(q.ends_at || ''));
    return isFinite(st) && isFinite(en) && nowMs >= st && nowMs <= en;
  });
  const quizRow = quizActive ? [{ text: t('menu.btn.quiz'), callback_data: 'qz:start' }] : [];

  let ticketText;
  let ticketReplyMarkup;
  if (hasEvent) {
    ticketText = [esc(t('ticket.header')), esc(t(online ? 'ticket.hint_online' : 'ticket.hint'))].join('\n\n');
    const rows = [[{ text: t('ticket.btn.open'), web_app: { url: base + '/#/ticket?event_id=' + eventId } }]];
    if (calUrl) rows.push([{ text: t('event.card.btn_calendar'), url: calUrl }]);
    if (quizRow.length) rows.push(quizRow);
    ticketReplyMarkup = { inline_keyboard: rows };
  } else {
    ticketText = esc(t('events.catalog.hint'));
    const rows = [[{ text: t('menu.btn.events'), web_app: { url: base + '/#/events' } }]];
    if (quizRow.length) rows.push(quizRow);
    ticketReplyMarkup = { inline_keyboard: rows };
  }
  return {
    ticketText: ticketText,
    ticketReplyMarkup: ticketReplyMarkup,
    now: new Date().toISOString()
  };
};

export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const isYes = str(inputs.callbackData) === 'reg:mkt:yes';
  let draft = {};
  try { draft = JSON.parse(str(inputs.sessionDraft) || '{}'); } catch (e) { draft = {}; }
  const eventId = str(draft.eventId);
  const utm = str(draft.utm);
  // ADR-0056: карточка не редактируется — cardMessageId не читается; финальное
  // сообщение (билет) уходит отдельной отправкой (step_9).
  return {
    isYes: isYes,
    consentValue: isYes ? 'true' : 'false',
    eventId: eventId,
    // W102: непустой sentinel для фильтра step_4 (пустой eq валит шаг).
    eventIdOrNone: eventId !== '' ? eventId : '__none__',
    utm: utm,
    now: new Date().toISOString()
  };
};
